import { AnimatePresence, motion } from "motion/react";

function calcTime(targetMs) {
  const diff = targetMs - Date.now();
  if (diff <= 0) return { days: 0, hours: 0, minutes: 0, seconds: 0, expired: true };
  return {
    days: Math.floor(diff / 86400000),
    hours: Math.floor((diff % 86400000) / 3600000),
    minutes: Math.floor((diff % 3600000) / 60000),
    seconds: Math.floor((diff % 60000) / 1000),
    expired: false,
  };
}

const INITIAL_TIME = { days: 0, hours: 0, minutes: 0, seconds: 0, expired: false };

function useCountdown(targetMs) {
  const [time, setTime] = React.useState(INITIAL_TIME);
  React.useEffect(() => {
    setTime(calcTime(targetMs));
    const id = setInterval(() => setTime(calcTime(targetMs)), 1000);
    return () => clearInterval(id);
  }, [targetMs]);
  return time;
}

const pad2 = (n) => String(n).padStart(2, "0");

const COUNTDOWN_FONT_MAP = {
  system: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
  mono: "'SF Mono', 'Fira Code', 'Consolas', 'Courier New', monospace",
  serif: "Georgia, 'Times New Roman', serif",
};

function FlipCell({ value, label, cellSize, radius, showLabel, labelPosition, colors }) {
  const digit = pad2(value);
  const digitSize = Math.round(cellSize * 0.43);
  const labelSize = Math.max(8, Math.round(digitSize * 0.52));

  return (
    <div className="cdt-flip-wrap" style={{ width: cellSize, height: cellSize }}>
      <div
        className={colors ? "cdt-flip-cell" : "cdt-flip-cell cdt-flip-cell--ambient"}
