          <motion.span
            key={digit}
            initial={{ y: "-100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: "100%", opacity: 0 }}
            transition={{ duration: 0.28, ease: [0.32, 0, 0.67, 0] }}
            className={colors ? "cdt-digit" : "cdt-digit cdt-digit--ambient"}
            style={{ fontSize: digitSize, ...(colors && { color: colors.digitColor }) }}
          >
            {digit}
          </motion.span>
        </AnimatePresence>
      </div>
      {showLabel && (
        <span
          className={`cdt-cell-label ${colors ? "" : "cdt-cell-label--ambient"} ${labelPosition === "top" ? "cdt-cell-label--top" : "cdt-cell-label--bottom"}`}
          style={{ fontSize: labelSize, ...(colors && { color: colors.labelColor }) }}
        >
          {label}
        </span>
      )}
    </div>
  );
}

function Colon({ size, blink, cellSize, color }) {
  const [visible, setVisible] = React.useState(true);
  React.useEffect(() => {
    if (!blink) return;
    const id = setInterval(() => setVisible((v) => !v), 1000);
    return () => clearInterval(id);
  }, [blink]);

  return (
    <div className="cdt-colon-wrap" style={{ height: cellSize }}>
      <span
        className={color ? "cdt-colon" : "cdt-colon cdt-colon--ambient"}
        style={{ fontSize: size, opacity: blink ? (visible ? 0.7 : 0.18) : 0.7, ...(color && { color }) }}
      >
        :
      </span>
    </div>
  );
}

